#include <iostream>

using std::cout;
using std::endl;

int main()
{
    int Stats[5];

    for (int i = 0; i < 5; i++)
    {
        Stats[i] = 0;
    }

    for (int i = 0; i < 5; i++)
    {
        cout << Stats[i] << " ";
    }
    cout << endl;

    for (int i = 0; i < 5; i++)
    {
        Stats[i] = (i + 1) * 10;
    }

    for (int i = 0; i < 5; i++)
    {
        cout << Stats[i] << " ";
    }
    cout << endl;

    return 0;
}

