#include <iostream>

using std::cout;
using std::endl;

int g_TotalScore = 0;

int main()
{
    for (int i = 1; i <= 5; i++)
    {
        int RoundScore = i;
        g_TotalScore += RoundScore;

        cout << "Round " << i << " - 점수: " << RoundScore << ", 총점: " << g_TotalScore << endl;
    }

    {
        int Bonus = 10;
        g_TotalScore += Bonus;
    }

    cout << "최종 총점: " << g_TotalScore << endl;

    return 0;
}
